it('answers UNSUPPORTED when history is disabled or store throws StoreCannotList', async () => {
  const inner = new InMemorySessionStore();
  const hal = createServer({
    app: (() => undefined) as unknown as Express,
    wsAuth: async () => ({id: 'u1'}),
    sessionStore: inner,
    orchestrator: answeringOrchestrator,
  });
  await hal.start(0);
  servers.push(hal);
  const port = (hal.server.address() as AddressInfo).port;
  const urlDisabled = `ws://127.0.0.1:${port}/hal/ws`;

  const cannotList = await startEngine({
    ...delegatingTo(inner),
    listFor: () => Promise.reject(new StoreCannotList('Not supported by this store')),
  });

  const res1 = await askAfterConnect(urlDisabled, {type: 'list_sessions'});
  const res2 = await askAfterConnect(cannotList, {type: 'list_sessions'});

  expect(res1.frames).toEqual([{type: 'error', code: 'UNSUPPORTED', message: 'History is not enabled'}]);
  expect(res2.frames).toEqual([{type: 'error', code: 'UNSUPPORTED', message: 'Not supported by this store'}]);
});

